effect.shader:

    mat2 rot2m(float a){

	float s = sin(a);
	float c = cos(a);

	return mat2(c, -s, s, c);
    }

    vec2 l2s( vec2 v ) {
        return (vec4(v,0.,1.)*acLayerToScreen).xy;
    }

   #define fragCoord gl_FragCoord

   /////////////////////////

   float wave(float x, float y) 
    {
        return sin(10.0*x+10.0*y) / 5.0 +
               sin(20.0*x+15.0*y) / 3.0 +
               sin(4.0*x+10.0*y) / -4.0 +
               sin(y) / 2.0 +
               sin(x*x*y*20.0) + 
               sin(x * 20.0 + 4.0) / 5.0 +
               sin(y * 30.0) / 5.0 + 
        	   sin(x) / 4.0; 

    }

   /////////////////////////
    void main ()
    {

        vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
        vec4 texColorX = vec4(0.0,0.0,0.0,1.0) * texColor.a;

        vec2 umefx;
        umefx = ((vec2(acScreenNorm.x,1.0-acScreenNorm.y)*acScreenSize)-acLayerCenter)/acLayerSize;
        umefx.y*=acLayerSize.y/acLayerSize.x;

        umefx /= scale;
        umefx *= rot2m((-180.0+angle)*0.0174533);
        umefx += vec2((0.0+position.x), (0.0+position.y))*vec2(-1.,1.)/500.;


        /////////////////////////

    	vec4 fragColor;

    	vec2 uv = umefx;

        float z = wave(uv.x, uv.y) + 2.0;


        z *= progressc * sin(1.57 + progressa / 5.0);
        float d = fract(z);
        if(mod(z, 2.0) > 1.) d = 1.-d;


        d = d/(progressb*z);
        fragColor = vec4(1.,1.,1.,1.) + ((1.-vec4(d)) + vec4(1.,1.,1.,1.));

    	    const vec3 luminanceWeighting = vec3(0.2126, 0.7152, 0.0722);
            vec4 gradmap;
            float luminance = dot(fragColor.rgb, luminanceWeighting);
            gradmap = mix(color1,color2,luminance)*fragColor.a;
    	    vec4 factor = mix(texColorX,gradmap,1.0);
    	// vec4 factor = mix(texColorX,fragColor,alpha);

        vec4 resultfinal;
        if( blendMode==0 ) {                // normal
            resultfinal = (factor * bright) * texColor.a;
        } else if( blendMode==1 ) {         // multiply
            factor *= bright;
            vec4 c = factor + vec4(1.)*(1.-factor.a);
            resultfinal = vec4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a;
        } else if( blendMode==2 ) {         // screen
            factor *= bright;
            resultfinal = vec4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-factor.rgb)),1.0) * texColor.a;
        }

    	gl_FragColor = mix(texColor,resultfinal,alpha);
    }
